export function pendingWorkflow(
	req: { repo: string },
	deps: UnaryRpcDeps = {},
): Promise<WorkflowPendingResult | WorkflowPendingError> {
	return unaryRpc<WorkflowPendingResult | WorkflowPendingError>('workflow.pending', req, deps);
}

'workflow.pending': async (params) => {
	const { handleWorkflowPending } = await import('../workflow/pending.js');
	return handleWorkflowPending(params as { repo?: string } | undefined, process.env['INSRC_REPO']);
},
